E=Path(__file__).parent;T=E.parents[1];W=T.parents[2];p=json.loads((E/'input-preservation.json').read_text());H=lambda x:hashlib.sha256(x.read_bytes()).hexdigest();git=lambda *x:subprocess.check_output(['git','-C',str(W),*x],env={**os.environ,'GIT_OPTIONAL_LOCKS':'0'});allowed={str(T/f) for f in ['requirements-doc.md','design-spec.md','investigation-notes.md','solution-revision-record.md','solution-design-handoff.md']}
