old=(E/'prior-solution-revision-record.md').read_text();new=(T/'solution-revision-record.md').read_text();cut=new.index('\n## SR-020 —');prefix='\n'.join(l for l in new[:cut].splitlines() if not l.startswith('| SR-020 |'))+'\n';assert prefix==old
for f in ['requirements-doc.md','design-spec.md','investigation-notes.md','solution-revision-record.md','solution-design-handoff.md']:assert H(E/('prior-'+f))==p['references'][str(T/f)]
