for args in [('diff','--check','HEAD'),('diff','--check','--cached')]:subprocess.run(['git','-C',str(W),*args],check=True,env={**os.environ,'GIT_OPTIONAL_LOCKS':'0'},stdout=subprocess.PIPE,stderr=subprocess.PIPE)
status=git('status','--porcelain=v1','-z');(E/'final-status.z').write_bytes(status);oldlines=(E/'input-status.z').read_bytes().split(b'\0');newlines=status.split(b'\0');nonlines=lambda xs:sorted(x for x in xs if x and not x[3:].startswith(b'tickets/'));assert nonlines(oldlines)==nonlines(newlines)
out={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'head':p['head'],'inputReferenceCount':len(p['references']),'missing':missing,'changedOnlyFiveDesignerCanonicals':changed,'299NonTicketBytesExact':len(p['nonTicket'])==299 and not non,'nonTicketStatusExact':True,'indexByteExact':True,'stagesExact':True,'zeroUnmerged':True,'exactPriorFiveArchives':True,'priorSR001to019ReconstructsByteExact':True,'currentManifestCount':len(refs),'allReferencesExist':True,'HEADAndCachedDiffChecks':0,'sourceDurableSpecialistGitNoChange':True,'scope':'Exact checkpoint before workflow handoff; new evidence/owned Designer docs only'};(E/'final-preservation.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out))
